"""FastAPI application entry point."""
from fastapi import FastAPI
from fastapi.staticfiles import StaticFiles
from fastapi.responses import FileResponse
from pathlib import Path

app = FastAPI(title="Mars Interactive Site")

FRONTEND_DIR = Path(__file__).parent.parent / "frontend"

@app.get("/")
async def serve_index():
    return FileResponse(FRONTEND_DIR / "index.html")

@app.get("/health")
async def health_check():
    return {"status": "ok"}

"""API route handlers."""
from fastapi import APIRouter
from .models import MarsFact, SoundTrigger, ApiResponse
from typing import List

router = APIRouter(prefix="/api/mars", tags=["mars"])

@router.get("/data", response_model=ApiResponse)
async def get_mars_data() -> ApiResponse:
    return ApiResponse(status="ok", data=[], message="Data endpoint ready")

@router.get("/sounds", response_model=ApiResponse)
async def get_sounds() -> ApiResponse:
    return ApiResponse(status="ok", data=[], message="Sounds endpoint ready")

:root {
    --color-bg: #0b0d17;
    --color-primary: #ff6b6b;
    --color-secondary: #4ecdc4;
    --color-text: #e0e0e0;
    --font-main: 'Segoe UI', system-ui, sans-serif;
    --transition-speed: 0.3s;
}

* { box-sizing: border-box; margin: 0; padding: 0; }
body { background: var(--color-bg); color: var(--color-text); font-family: var(--font-main); }
#main-header { position: fixed; top: 0; width: 100%; z-index: 100; background: rgba(11,13,23,0.9); }
#main-nav { display: flex; justify-content: center; gap: 2rem; padding: 1rem; }
#main-nav a { color: var(--color-text); text-decoration: none; transition: color var(--transition-speed); }
#main-nav a:hover { color: var(--color-primary); }
#app-root { padding-top: 80px; min-height: 100vh; }
#hero { height: 100vh; display: flex; align-items: center; justify-content: center; }
#mars-hero-svg { width: 100%; max-width: 600px; }

import { initAudio } from './audio.js';
import { initAnimations } from './animations.js';
import { fetchMarsData } from './utils.js';

export async function init() {
    console.log('Initializing Mars Site...');
    initAudio();
    initAnimations();
    try {
        const data = await fetchMarsData();
        console.log('Mars data loaded:', data);
    } catch (err) {
        console.error('Failed to load Mars data:', err);
    }
}

document.addEventListener('DOMContentLoaded', init);

export function initAnimations() {
    console.log('Animation system initialized');
}

export function triggerAnimation(selector, type, duration = 1000) {
    const el = document.querySelector(selector);
    if (!el) return;
    console.log(`Triggering ${type} animation on ${selector}`);
}

export function setupScrollAnimations() {
    console.log('Scroll animations configured');
}

export function initSvgEngine() {
    console.log('SVG engine initialized');
}

export function renderSvgPath(svgId, pathData, duration = 1000) {
    console.log(`Rendering path on ${svgId}`);
}

export function animateSvgRotation(svgId, degrees, duration = 2000) {
    console.log(`Rotating ${svgId}`);
}

let audioContext = null;

export function initAudio() {
    audioContext = new (window.AudioContext || window.webkitAudioContext)();
    console.log('Audio context initialized');
}

export function playSound(eventId) {
    if (!audioContext) return;
    console.log(`Playing sound: ${eventId}`);
}

export function attachAudioTriggers() {
    console.log('Audio triggers attached');
}

export function loadSoundManifest(url) {
    console.log(`Loading sound manifest from ${url}`);
    return Promise.resolve([]);
}

export function registerSoundTrigger(eventId, soundUrl) {
